// The tabs and sections of the French pages.
const KB_SS_SEC_FR = { Behaviour: 'Comportement', Essentials: 'Essentiel', 'Glass and background': 'Verre et fond', Colors: 'Couleurs', 'Text and shape': 'Texte et forme', Animation: 'Animation', Icons: 'Icônes', Accessibility: 'Accessibilité' }
const KB_SS_STOP = ['the', 'of', 'my', 'le', 'la', 'les', 'de', 'des', 'du', 'un', 'une', 'a', 'to', 'in', 'el', 'los']
const kbSsNorm = (s) => {
  try { return String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim() } catch (e) { return String(s || '').toLowerCase().trim() }
}
const kbSsToks = (s) => kbSsNorm(s).split(' ').filter((t) => t !== '')
// The translation pack other languages are served from (the Language page translates the French of every pack bundles publish in
// window.__KB_I18N_PACKS__; the result is read back under « settingsidx.<key> »): a stable key per row, from its page and its label.
const KB_SS_PACK = 'settingsidx'
const kbSsSlug = (page, label) => kbSsNorm(page + ' ' + label).replace(/ /g, '-')
/** The strings of a row in a language: { sec, label, desc, at }. French from KB_SS_FR, any other translated language from its pack, else English. */
const kbSsLocalise = (r, lang, pack) => {
  const en = { sec: r[1], label: r[2], desc: r[3], at: r[7] || r[2] }
  const base = String(lang === undefined || lang === null ? 'en' : lang).split(/[-_]/)[0]
  if (base === 'kybernos' || base === 'fr') {
    const f = KB_SS_FR[r[0] + '|' + r[2]]
    return { sec: KB_SS_SEC_FR[r[1]] === undefined ? r[1] : KB_SS_SEC_FR[r[1]], label: f === undefined ? en.label : f[0], desc: f === undefined ? en.desc : f[1], at: f === undefined ? en.at : (f[2] || f[0]) }
  }
  if (base === 'en' || pack === undefined || pack === null) return en
  const slug = kbSsSlug(r[0], r[2])
  const get = (k, d) => { const v = pack[KB_SS_PACK + '.' + slug + '.' + k]; return typeof v === 'string' && v !== '' ? v : d }
  const sv = pack[KB_SS_PACK + '.sec.' + kbSsSlug('', r[1])]
  const label = get('l', en.label)
  return { sec: r[1] === '' || typeof sv !== 'string' || sv === '' ? r[1] : sv, label, desc: get('d', en.desc), at: get('a', label === en.label ? en.at : label) }
}
/** What this index adds to the translation corpus: { key: { fr, en } } for every label, description, text to go to and section. */
const kbSsPackKeys = (rows) => {
  const keys = {}
  for (const r of rows) {
    const f = KB_SS_FR[r[0] + '|' + r[2]]
    const slug = kbSsSlug(r[0], r[2])
    keys[slug + '.l'] = { fr: f === undefined ? r[2] : f[0], en: r[2] }
    const frDesc = f === undefined ? r[3] : f[1]
    if (r[3] !== '' && frDesc !== '') keys[slug + '.d'] = { fr: frDesc, en: r[3] }
    if (r[7]) keys[slug + '.a'] = { fr: f !== undefined && f[2] ? f[2] : r[7], en: r[7] }
    if (r[1] !== '') keys['sec.' + kbSsSlug('', r[1])] = { fr: KB_SS_SEC_FR[r[1]] === undefined ? r[1] : KB_SS_SEC_FR[r[1]], en: r[1] }
  }
  return keys
}
// Edit distance with swapped neighbours counted as one edit (« theem » for « theme »).
const kbSsLev = (a, b, max) => {
  const m = a.length
  const n = b.length
  if (Math.abs(m - n) > max) return max + 1
  const d = []
  for (let i = 0; i <= m; i += 1) d[i] = [i]
  for (let j = 0; j <= n; j += 1) d[0][j] = j
  for (let i = 1; i <= m; i += 1) {
    for (let j = 1; j <= n; j += 1) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1))
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1)
    }
  }
  return d[m][n]
}
// A typo is forgiven in words of five letters or more that start alike: one edit, two from eight letters. Short words never (« font » is not « fond »).
const kbSsNear = (q, words) => {
  if (q.length < 5) return null
  const max = q.length >= 8 ? 2 : 1
  for (const w of words) if (w.length >= 4 && w[0] === q[0] && kbSsLev(q, w, max) <= max) return w
  return null
}
/** The index, ready to search in a language: every row with its words cut once. What the page draws in that language is what is shown and what
 *  the label words are cut from; the English label, description and section stay searchable too (a French reader may type « font size »). */
const kbSsBuild = (rows, lang, pack) => rows.map((r, i) => {
  const L = kbSsLocalise(r, lang, pack)
  return {
    i, page: r[0], sec: L.sec, label: L.label, desc: L.desc, opts: r[4], kw: r[5], dup: r[6] || null, at: L.at, key: r[0] + '|' + r[2],
    lt: kbSsToks(L.label), kt: kbSsToks(r[5] + (L.label === r[2] ? '' : ' ' + r[2])), dt: kbSsToks(L.desc + (L.desc === r[3] ? '' : ' ' + r[3])), ot: kbSsToks(r[4]),
    st: kbSsToks(L.sec + (L.sec === r[1] ? '' : ' ' + r[1]))
  }
})
// One word of the query against one row: the best field it hits, its score, and the word that did.
const kbSsWord = (q, e, pageToks) => {
  let best = { s: 0, f: '', w: '' }
  const put = (s, f, w) => { if (s > best.s) best = { s, f, w } }
  for (const t of e.lt) { if (t === q) put(12, 'label', t); else if (q.length >= 2 && t.startsWith(q)) put(10, 'label', t); else if (q.length >= 3 && t.includes(q)) put(6, 'label', t) }
  for (const t of e.kt) { if (t === q) put(8, 'kw', t); else if (q.length >= 3 && t.startsWith(q)) put(7, 'kw', t) }
  for (const t of e.ot) { if (t === q) put(9, 'value', t); else if (q.length >= 3 && t.startsWith(q)) put(6, 'value', t) }
  for (const t of e.dt) { if (t === q) put(3, 'desc', t); else if (q.length >= 3 && t.startsWith(q)) put(2, 'desc', t) }
  for (const t of e.st.concat(pageToks)) { if (t === q || (q.length >= 3 && t.startsWith(q))) put(2, 'page', t) }
  if (best.s < 6) {
    const a = kbSsNear(q, e.lt)
    if (a !== null) put(6, 'typo', a)
    else { const b = kbSsNear(q, e.kt); if (b !== null) put(5, 'typo', b) }
  }
  return best
}
/**
 * Search the Settings.   entries: kbSsBuild(KB_SS_INDEX)   titles: { pageKey: title as drawn in the menu now } (one per page that exists)
 * Returns { list, total }: list is what to show, in order — { kind: 'page', key, rel, typo } for a page found by its title (or typo of it),
 * { kind: 'item', e, also, why } for a setting (also: the same setting shown on other pages, why: what matched besides the label), and the pages
 * found only by a related word last. A setting that two pages both show (the mode, the text size) is one result.
 */
const kbSsSearch = (query, entries, titles) => {
  const qs = kbSsToks(query).filter((t) => KB_SS_STOP.indexOf(t) === -1)
  if (qs.length === 0) return { list: [], total: 0 }
  const full = kbSsNorm(query)
  const pageToks = (key) => kbSsToks(titles[key] || '')
  const hits = []
  for (const e of entries) {
    if (titles[e.page] === undefined) continue // the page is not in this menu (a module switched off): its rows are not either
    let total = 0
    const why = []
    for (const q of qs) {
      const w = kbSsWord(q, e, pageToks(e.page))
      if (w.s === 0) { total = 0; break }
      total += w.s
      if (w.f === 'kw' || w.f === 'value' || w.f === 'typo') why.push({ q, f: w.f, w: w.w })
    }
    if (total === 0) continue
    if (kbSsNorm(e.label).indexOf(full) !== -1) total += 8
    hits.push({ e, s: total, why })
  }
  const canon = (e) => (e.dup === 'mode' ? e.page === 'theme' : e.dup === 'fs' ? e.page === 'general' : true)
  hits.sort((a, b) => b.s - a.s || (canon(b.e) ? 1 : 0) - (canon(a.e) ? 1 : 0) || a.e.i - b.e.i)
  const seen = new Map()
  const items = []
  for (const h of hits) {
    h.also = []
    if (h.e.dup !== null) {
      if (seen.has(h.e.dup)) { seen.get(h.e.dup).also.push(h.e); continue }
      seen.set(h.e.dup, h)
    }
    items.push(h)
  }
  const pages = []
  for (const key of Object.keys(titles)) {
    const tt = pageToks(key)
    const kk = kbSsToks(KB_SS_PAGE_KW[key] || '')
    let ok = true
    let typo = null
    let rel = null
    for (const q of qs) {
      if (tt.some((t) => t === q || (q.length >= 2 && t.startsWith(q)))) continue
      if (q.length >= 3 && kk.some((t) => t === q || t.startsWith(q))) { rel = q; continue }
      const n = kbSsNear(q, tt)
      if (n !== null) { typo = { q, w: n }; continue }
      ok = false
      break
    }
    if (ok) pages.push({ kind: 'page', key, typo, rel })
  }
  const list = pages.filter((p) => p.rel === null).slice(0, 3)
    .concat(items.slice(0, 8).map((h) => ({ kind: 'item', e: h.e, also: h.also, why: h.why })))
    .concat(pages.filter((p) => p.rel !== null).slice(0, 2))
  return { list, total: list.length }
}
// </kb-settings-search>

// ── DSH's Settings, opened from outside the sidebar (<kb-open-settings>) ─────────────────────────────────────
// The sidebar's settings seat renders DSH's ACCOUNT launcher (slot `settings.launcher`) whenever the account plugin is mounted, and
// the trigger of that launcher opens an account popover (Settings / Feedback / Sign in), not the Settings dialog. Everything that
// clicked « the trigger of the settings area » to reach Settings therefore opened that popover instead (seen on DSH 0.2.1-alpha.4).
// The opener of the dialog is the launcher's own `openSettings` prop (contract: SettingsLauncherOwnerProps): read it from React and
// call it. Fallbacks, in order: the dialog trigger the shell renders when NO launcher is registered, then the launcher's own popover
// (its first entry is Settings; it is kept invisible while that entry is picked). Nothing depends on a hashed class name: slot
// names and ARIA are DSH's contract; React's fiber fields have been stable for years and the ladder survives their loss.
let kbOpeningSettings = false
const kbReactSettingsOpener = () => {
  try {
    const launcher = document.querySelector('[data-slot="settings.launcher"]')
    if (launcher === null) return null
    const nodes = [launcher].concat(Array.prototype.slice.call(launcher.querySelectorAll('*'), 0, 6))
    for (const node of nodes) {
      const key = Object.keys(node).find((x) => x.indexOf('__reactFiber$') === 0)
      let fiber = key === undefined ? null : node[key]
      for (let depth = 0; fiber !== null && fiber !== undefined && depth < 30; depth += 1, fiber = fiber.return) {
        const p = fiber.memoizedProps
        if (p === null || p === undefined || typeof p !== 'object') continue
        // The launcher component itself, then (further up) the settings root that handed it the prop.
        if (typeof p.openSettings === 'function') return p.openSettings
        if (p.actions !== null && typeof p.actions === 'object' && typeof p.actions.open === 'function' && typeof p.renderSlot === 'function') return p.actions.open
      }
    }
  } catch (e) { /* React internals moved: the fallbacks are next */ }
  return null
}
/** Opens DSH's Settings dialog. `true` when something was triggered (the popover route finishes a moment later). */
const kbOpenDshSettings = () => {
  const opener = kbReactSettingsOpener()
  if (opener !== null) {
    try { opener(); return true } catch (e) { /* fall through */ }
  }
  try {
    // An engine older than the account launcher draws the plain trigger: found by ARIA, then by its (hashed) class as before.
    const dialogTrigger = document.querySelector('[data-slot="sidebar.settings"] button[aria-haspopup="dialog"]')
    if (dialogTrigger !== null) { dialogTrigger.click(); return true }
    const legacy = document.querySelector('[class*="settingsArea"] button[class*="trigger"]')
    if (legacy !== null && legacy.getAttribute('aria-haspopup') !== 'menu' && legacy.closest('[data-slot="settings.launcher"]') === null) { legacy.click(); return true }
  } catch (e) { /* fall through */ }
  try {
    const trigger = document.querySelector('[data-slot="settings.launcher"] button')
    if (trigger === null) return false
    const veil = document.createElement('style')
    veil.textContent = '[role="menu"]{visibility:hidden !important}'
    document.head.appendChild(veil)
    kbOpeningSettings = true
    try { trigger.click() } finally { kbOpeningSettings = false }
    let tries = 0
    const pick = () => {
      tries += 1
      const item = document.querySelector('[role="menu"] [role="menuitem"]')
      if (item !== null) {
        try { item.click() } catch (e) { /* popover gone */ }
        veil.remove()
        return
      }
      if (tries < 20) { window.setTimeout(pick, 25); return }
      // No entry showed up: close the popover again and give up quietly.
      veil.remove()
      if (trigger.getAttribute('aria-expanded') === 'true') {
        kbOpeningSettings = true
        try { trigger.click() } finally { kbOpeningSettings = false }
      }
    }
    window.setTimeout(pick, 0)
    return true
  } catch (e) { return false }
}
/**
 * A click on DSH's account launcher never reaches its popover while the Kybernos footer is there:
 *  - a script's click (`isTrusted` false) is a plugin reaching for Settings through the old trigger: it gets Settings;
 *  - a real click (the shell's class names moved and the launcher showed up) lands in the footer's own menu.
 * Without a Kybernos footer a real click is left to DSH. Capture phase on the document: it runs before React's root listener.
 */
const kbInstallLauncherGuard = () => {
  const onClick = (ev) => {
    if (kbOpeningSettings === true) return
    const target = ev.target
    if (target === null || target === undefined || typeof target.closest !== 'function') return
    if (target.closest('[data-slot="settings.launcher"]') === null) return
    if (ev.isTrusted !== true) {
      ev.preventDefault()
      ev.stopImmediatePropagation()
      kbOpenDshSettings()
      return
    }
    if (document.querySelector('[data-kb="foot-signin"], [data-kb="workspace-card"]') === null) return
    ev.preventDefault()
    ev.stopImmediatePropagation()
    try { window.dispatchEvent(new Event('kybernos-cloud:menu')) } catch (e) { /* no Event */ }
  }
  document.addEventListener('click', onClick, true)
  try { window.__kbOpenDshSettings = kbOpenDshSettings } catch (e) { /* no window */ }
  return () => {
    document.removeEventListener('click', onClick, true)
    try { if (window.__kbOpenDshSettings === kbOpenDshSettings) delete window.__kbOpenDshSettings } catch (e) { /* no window */ }
  }
}
// </kb-open-settings>

/**
 * Opens DSH's Settings on a page, by the id of its section (« kybernos-models »): the dialog first, then the cell of that page, read from the cell's React
 * key (the same in every language), with the English title as the fallback when the shell's internals moved. `names` are tried in order. The wizard's
 * « Change » links and the « no model » card of the chat share it.
 */
const kbOpenSettingsPage = (names) => {
  try {
    if (kbOpenDshSettings() !== true) return
    const norm = (s) => String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g'), '').replace(/\s+/g, ' ').trim()
    let tries = 0
    const tick = () => {
      tries += 1
      const cells = Array.prototype.slice.call(document.querySelectorAll('nav button'))
      for (const name of names) {
        let hit = cells.find((c) => { try { return kbNavKeyOf(c) === name } catch (e) { return false } })
        if (hit === undefined && typeof KB_NAV_KEYS === 'object' && typeof KB_NAV_KEYS[name] === 'string') hit = cells.find((c) => norm(c.textContent) === KB_NAV_KEYS[name])
        if (hit !== undefined) { hit.click(); return }
      }
      if (tries < 25) window.setTimeout(tick, 120)
    }
    window.setTimeout(tick, 150)
  } catch (e) { /* the shell moved: the person opens Settings by hand */ }
}

