const kbComposioConnections = (slugs) => {
  const list = Array.isArray(slugs) ? slugs.filter((x) => typeof x === 'string' && x.length > 0).slice(0, 40) : []
  const key = list.slice().sort().join(',')
  if (kbConnCache[key] !== undefined) return kbConnCache[key]
  if (kbConnBusy[key] !== true && kbRemoteOk === true) {
    kbConnBusy[key] = true
    // Aucun secret ici : la route du plugin Composio resout la cle cote host.
    fetch(kbApiBase() + '/composio/connections?toolkits=' + encodeURIComponent(list.join(',')))
      .then((r) => (r.ok === true ? r.json() : null))
      .then((body) => {
        kbConnCache[key] = (body !== null && body !== undefined && body.ok === true)
          ? body
          : { ok: false, missing: true, configured: false, connections: [] }
        kbBumpConn()
      })
      .catch(() => { kbConnCache[key] = { ok: false, offline: true, configured: false, connections: [] }; kbBumpConn() })
  }
  return null
}
// Activer / desactiver une connexion deja etablie, depuis la page projet : par la
// route d'hote du plugin Composio (`/composio/accounts`), qui seule porte la cle,
// et la meme route de lecture pour le rafraichissement.
const kbConnForget = () => {
  for (const k of Object.keys(kbConnCache)) delete kbConnCache[k]
  // The « busy » flags go too: left set, the re-read never started and the list stayed on « Reading… » until the page was reloaded.
  for (const k of Object.keys(kbConnBusy)) delete kbConnBusy[k]
  kbBumpConn()
}
// Ce que le COMPTE a connecte, vu depuis la page projet. Le MCP exige des noms
// (mesure : « At least one toolkit is required ») : on prend les candidats du
// catalogue local servi par l'hote (100 apps) et on interroge par lots de 40,
// plafond de la route. Seuls les toolkits qui PORTENT un compte sont gardes.
const kbConnScan = () => {
  const cle = '__scan__'
  if (kbConnCache[cle] !== undefined) return kbConnCache[cle]
  if (kbConnBusy[cle] !== true && kbRemoteOk === true) {
    kbConnBusy[cle] = true
    fetch(kbApiBase() + '/composio/catalog')
      .then((r) => (r.ok === true ? r.json() : null))
      .then((cat) => {
        const apps = Array.isArray(cat) === true ? cat : ((cat !== null && cat !== undefined && Array.isArray(cat.apps) === true) ? cat.apps : [])
        const slugs = []
        const vus = {}
        for (const a of apps) {
          const s = (a !== null && a !== undefined && typeof a.s === 'string') ? a.s : ((a !== null && a !== undefined && typeof a.slug === 'string') ? a.slug : '')
          if (s.length === 0 || vus[s] === true) continue
          vus[s] = true
          slugs.push(s)
        }
        if (slugs.length === 0) throw new Error(kbe('catalogue unavailable'))
        const lots = []
        for (let i = 0; i < slugs.length; i += 40) lots.push(slugs.slice(i, i + 40))
        return Promise.all(lots.map((lot) => fetch(kbApiBase() + '/composio/connections?toolkits=' + encodeURIComponent(lot.join(',')))
          .then((r) => (r.ok === true ? r.json() : null))
          .catch(() => null)))
      })
      .then((reponses) => {
        const out = []
        let configure = false
        for (const body of reponses) {
          if (body === null || body === undefined) continue
          if (body.configured === true) configure = true
          for (const c of (Array.isArray(body.connections) === true ? body.connections : [])) {
            if (c !== null && c !== undefined && Array.isArray(c.accounts) === true && c.accounts.length > 0) out.push(c)
          }
        }
        kbConnCache[cle] = { ok: true, configured: configure, connections: out, scan: true }
        kbBumpConn()
      })
      .catch(() => { kbConnCache[cle] = { ok: false, offline: true, configured: false, connections: [], scan: true }; kbBumpConn() })
  }
  return null
}
/**
 * Fusion commune au projet et a la fiche d'equipe : ce que les roles DECLARENT
 * (champ tools: du kyber.yml), puis ce que le COMPTE a connecte en plus, sans
 * doublon de toolkit. `actif` faux => aucun appel reseau (onglet ferme).
 */
/** Outils reclames dans un kyber.yml : `tools:` / `connectors:` (listes en ligne). */
const kbYmlTools = (texte) => {
  const out = []
  let role = ''
  for (const ligne of String(texte === null || texte === undefined ? '' : texte).split('\n')) {
    const rid = /^\s*-\s*id:\s*([^\s#]+)/.exec(ligne)
    if (rid !== null) { role = rid[1]; continue }
    const lst = /^(\s*)(?:tools|connectors):\s*\[([^\]]*)\]/.exec(ligne)
    if (lst === null) continue
    for (const brut of lst[2].split(',')) {
      const nom = brut.trim().replace(/^['"]/, '').replace(/['"]$/, '')
      // Sans indentation, le besoin est celui de l'EQUIPE, pas d'un role.
      if (nom.length > 0) out.push({ nom: nom, role: lst[1].length === 0 ? '' : role })
    }
  }
  return out
}

const kbConnMerge = (slugs, actif) => {
  if (actif !== true) return null
  const declaration = kbComposioConnections(slugs)
  const balayage = kbConnScan()
  // Des outils declares : tant que leur etat est en lecture, on l'annonce — le
  // balayage ne doit pas parler a leur place.
  if (declaration === null && slugs.length > 0) return null
  if (declaration === null) return balayage
  if (balayage === null) return declaration
  const vus = {}
  const out = []
  for (const c of (Array.isArray(declaration.connections) === true ? declaration.connections : [])) { vus[c.toolkit] = true; out.push(c) }
  for (const c of (Array.isArray(balayage.connections) === true ? balayage.connections : [])) if (vus[c.toolkit] !== true) out.push(c)
  // Si la route des outils declares a echoue, c'est le balayage qui porte la
  // verite (et ses drapeaux) : on ne garde pas un « route absente » faux.
  const base = (declaration.missing === true || declaration.offline === true) ? balayage : declaration
  return Object.assign({}, base, { connections: out, scan: balayage.scan === true || declaration.scan === true })
}

// What the Skills page knows of each skill (its description, when to use it, where it lives): read once a minute from the Skills plugin,
