        if (j === null || j === undefined || Array.isArray(j.skills) !== true) return null
        const out = {}
        for (const x of j.skills) { const k = String(x.name === undefined || x.name === null ? '' : x.name).toLowerCase(); if (k !== '' && out[k] === undefined) out[k] = x }
        return out
