      const kyberId = (kyber !== null && kyber.id !== null && kyber.id !== undefined && String(kyber.id).trim() !== '') ? String(kyber.id) : null
      const fige = (p.quality !== null && p.quality !== undefined) ? p.quality : null
      const pairD = React.useState(fige)
      const data = pairD[0]
