function mixHex(a,b,t){
  const A = hexRgb(a), B = hexRgb(b);
  return '#' + [0,1,2].map(i => clamp(Math.round(A[i]+(B[i]-A[i])*t),0,255).toString(16).padStart(2,'0')).join('');
}

