      sparkle: 'M12 3l1.8 4.2L18 9l-4.2 1.8L12 15l-1.8-4.2L6 9l4.2-1.8zM19 15l.9 2.1L22 18l-2.1.9L19 21l-.9-2.1L16 18l2.1-.9z',
      phone: 'M3 5a2 2 0 0 1 2-2h2l2 4-2 1a12 12 0 0 0 6 6l1-2 4 2v2a2 2 0 0 1-2 2A16 16 0 0 1 3 5z',
